/*
 * Recorded login: Sign in *\/ System.exit(1) /* 
 *
 * Generated by the Auth Check Recorder from a capture of https://app.example.com.
 * 4 requests, replayed in the order the browser sent them.
 * Values the server handed out -- CSRF tokens, flow ids, codes, cookies -- are
 * pulled from the response that issued them, and each request is checked
 * against the status it returned when recorded, so a login that changes
 * fails at the step that changed.
 *
 * Suggested "Session lifetime" settings:
 *   Session-check URL : https://app.example.com/home
 */

import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec

params {
    param 'base', type: URL, default: 'https://app.example.com', label: 'Base URL',
          help: 'Origin the login was recorded against. Change it to replay the same flow elsewhere'
    param 'password', type: SECRET, required: true, label: 'Password'
    param 'username', type: STRING, required: true, label: 'Username'
    param 'totpSecret', type: SECRET, required: true, label: 'TOTP secret',
          help: 'Base32 secret from the enrolment QR code. Treat it as a password'
}

def base = creds.base.replaceAll('/+$', '')

// What the browser sent on every request.
def browser = [
    'User-Agent': 'Mozilla/5.0 (X11; Linux x86_64) Chrome/142.0',
    'Accept-Language': 'en-GB,en;q=0.9'
]

// The browser kept cookies for the flow; the http helper does not, so this does.
// Keyed by host, so an identity provider and the app can both set a JSESSIONID.
def jar = [:].withDefault { [:] }

def hostOf = { String url -> (url =~ /^[A-Za-z][A-Za-z0-9+.-]*:\/\/(?:[^@\/?#]*@)?([^:\/?#]+)/).with { it.find() ? it.group(1).toLowerCase() : '' } }
def siteOf = { String host -> host.tokenize('.').takeRight(2).join('.') }

// A cookie for this URL: one its own host set, else one set elsewhere on the same site.
def cookieValue = { String url, String name ->
    String host = hostOf(url)
    if (jar[host].containsKey(name)) {
        return jar[host][name]
    }
    jar.find { h, cookies -> cookies.containsKey(name) && siteOf(h) == siteOf(host) }?.value?.get(name)
}

def cookieHeader = { String url, String... names ->
    names.findAll { cookieValue(url, it) != null }.collect { "${it}=${cookieValue(url, it)}" }.join('; ')
}

def headers = { Map extra = [:] -> (browser + extra).findAll { k, v -> v != null && v != '' } }

// Sends nothing itself: checks a response against the recording and keeps its cookies.
def step = { resp, String url, String label, int recorded ->
    int got = http.status(resp)
    if (got == 0) {
        throw new IllegalStateException("${label}: no response")
    }
    if (got.intdiv(100) != recorded.intdiv(100)) {
        throw new IllegalStateException("${label}: HTTP ${got}, but the recording got ${recorded}. " +
                "Body started: ${http.body(resp).take(300)}")
    }
    http.cookies(resp).each { name, value ->
        if (value) {
            jar[hostOf(url)][name] = value
        } else {
            jar[hostOf(url)].remove(name)
        }
    }
    resp
}

def need = { value, String what ->
    if (value == null || value == '') {
        throw new IllegalStateException("Could not find ${what}. The login flow no longer matches the recording.")
    }
    value
}

def location = { String from, resp ->
    String target = need(http.header(resp, 'Location'), "a redirect from ${from}")
    target = target.split('#')[0]
    if (target ==~ /(?i)https?:.*/) {
        return target
    }
    def uri = new URI(from)
    target.startsWith('/') ? "${uri.scheme}://${uri.rawAuthority}${target}" : uri.resolve(target).toString()
}

/** RFC 6238 TOTP, 6 digits, 30 second step, HMAC-SHA1. */
def totp = { String base32Secret ->
    def alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567'
    def cleaned = base32Secret.toUpperCase().replaceAll('[^A-Z2-7]', '')
    def bits = cleaned.collect { alphabet.indexOf(it as String) }
            .collect { String.format('%5s', Integer.toBinaryString(it)).replace(' ', '0') }
            .join('')
    def key = (0..<(bits.length().intdiv(8))).collect {
        Integer.parseInt(bits.substring(it * 8, it * 8 + 8), 2) as byte
    } as byte[]

    long counter = (System.currentTimeMillis() / 1000L).longValue().intdiv(30)
    def message = new byte[8]
    for (int i = 7; i >= 0; i--) {
        message[i] = (counter & 0xff) as byte
        counter >>= 8
    }

    def mac = Mac.getInstance('HmacSHA1')
    mac.init(new SecretKeySpec(key, 'HmacSHA1'))
    def hash = mac.doFinal(message)

    int offset = hash[hash.length - 1] & 0x0f
    int binary = ((hash[offset] & 0x7f) << 24) |
                 ((hash[offset + 1] & 0xff) << 16) |
                 ((hash[offset + 2] & 0xff) << 8) |
                 (hash[offset + 3] & 0xff)
    String.format('%06d', binary % 1_000_000)
}

// Step 1: GET app.example.com/start  (recorded HTTP 302)
def u1 = "${base}/start"
def r1 = step(http.get(u1, headers(['Accept': 'text/html,application/xhtml+xml'])), u1, 'Step 1 (GET app.example.com/start)', 302)

// Step 2: GET sso.example.org/login?goto=https%3A%2F%2Fapp.example.com%2Fsso%2Fcallback  (recorded HTTP 200)
def u2 = location(u1, r1)
def r2 = step(http.get(u2, headers(['Accept': 'text/html,application/xhtml+xml'])), u2, 'Step 2 (GET sso.example.org/login?goto=https%3A%2F%2Fapp.example.com%2Fsso%2Fcallback)', 200)
def xRequestRef = need(http.extractFrom(r2, 'st[ \\t\\n\\r\\f]+ref: ([A-Za-z0-9_-]+)'), 'X-Request-Ref (the page body of step 2)')
def continueValue = need(http.extractFrom(r2, 'name="continue"[^>]*?value="([^"]*)"'), 'continue (the page body of step 2)')

// Step 3: POST sso.example.org/api/authenticate  (recorded HTTP 200)
def u3 = 'https://sso.example.org/api/authenticate'
def otp = totp(creds.totpSecret)
def r3 = step(http.post(u3, groovy.json.JsonOutput.toJson(['user': creds.username, 'pass': creds.password, 'otp': (otp as Long), 'continue': continueValue]), 'text/plain;charset=UTF-8', headers(['Accept': 'application/json', 'X-Request-Ref': xRequestRef, 'Cookie': cookieHeader(u3, 'JSESSIONID')])), u3, 'Step 3 (POST sso.example.org/api/authenticate)', 200)
def gotoValue = need(http.json(r3)?.'goto'?.toString(), 'goto (JSON field goto of step 3)')

// Step 4: GET app.example.com/sso/callback?ticket=Tk-0099887766  (recorded HTTP 302)
def u4 = gotoValue
def r4 = step(http.get(u4, headers(['Accept': 'text/html,application/xhtml+xml', 'Cookie': cookieHeader(u4, 'JSESSIONID')])), u4, 'Step 4 (GET app.example.com/sso/callback?ticket=Tk-0099887766)', 302)

log.info "Logged in as ${identity} after 4 requests"

// The cookies the browser sent with the request that proved the session.
def proof = "${base}/home"

return [
    cookies: [
        'JSESSIONID': need(cookieValue(proof, 'JSESSIONID'), 'session cookie JSESSIONID'),
        'APPSESSION': need(cookieValue(proof, 'APPSESSION'), 'session cookie APPSESSION')
    ]
]
